import { useMemo, useState } from 'react';
import { useIntl } from 'react-intl';

import {
  BasicContainer,
  DataStateHandler,
  SegmentedControl2,
  SegmentedControl2Option,
  Skeleton,
  SubFilter,
} from 'components';
import { TableDataType } from 'components/Table/types';
import { WaterfallConfig } from 'pages/pillars/ValueCreation/PerformanceTool/config';
import { PERFORMANCE_CHART_SECTION_BODY_HEIGHT } from 'pages/pillars/ValueCreation/PerformanceTool/constants/chartSectionLayout';
import { useWaterfallSection } from 'pages/pillars/ValueCreation/PerformanceTool/hooks/useWaterfallSection/useWaterfallSection';
import { useWaterfallViewBySync } from 'pages/pillars/ValueCreation/PerformanceTool/hooks/useWaterfallViewBySync';
import { WaterfallSectionData } from 'pages/pillars/ValueCreation/PerformanceTool/types';
import { normalizeKpiConfig } from 'pages/pillars/ValueCreation/PerformanceTool/utils';

import { KpiDrillDownTable } from '../../../KpiDrillDownTable/KpiDrillDownTable';
import { WaterfallContent } from '../WaterfallContent';
import { StyledDrillDownTable } from './WaterfallSection.styles';

interface WaterfallSectionProps {
  config: WaterfallConfig;
  title: string;
  measure?: string;
  tooltip?: string;
  data?: WaterfallSectionData;
  loading: boolean;
  error?: Error | null;
  variant?: 'large' | 'small';
  viewByDataApiKey?: string;
  viewByApiKeyPrefix?: string;
  skeletonProps?: React.ComponentProps<typeof Skeleton>;
  tableData?: TableDataType;
  segmentedControlOptions?: SegmentedControl2Option[];
}

export const WaterfallSection: React.FC<WaterfallSectionProps> = ({
  config,
  title,
  measure,
  tooltip,
  loading,
  error,
  data,
  variant = 'large',
  viewByDataApiKey = 'performance-tool-waterfall-options',
  viewByApiKeyPrefix = 'performance-tool-waterfall-options',
  skeletonProps = {
    height: PERFORMANCE_CHART_SECTION_BODY_HEIGHT,
    width: '100%',
    length: 1,
    borderRadius: 'none',
  },
  tableData,
  segmentedControlOptions,
}) => {
  const { formatMessage } = useIntl();
  const [selectedView, setSelectedView] = useState<'chart' | 'table'>('chart');

  const {
    chartData,
    contextKey,
    isViewByDisabled,
    disabledIndexes,
    handleBarClick,
    legendItems,
    shouldShowLegend,
  } = useWaterfallSection({ config, data, variant });

  const { handleViewByChange } = useWaterfallViewBySync({ config, contextKey });

  const hasTableView = Boolean(tableData);

  const segmentControl = useMemo(
    () =>
      hasTableView ? (
        <SegmentedControl2
          value={selectedView}
          onValueChange={(value) => setSelectedView(value as 'chart' | 'table')}
          options={segmentedControlOptions ?? []}
        />
      ) : null,
    [hasTableView, selectedView, segmentedControlOptions],
  );

  const rightContent = useMemo(
    () => (
      <>
        {segmentControl}
        <SubFilter.Select
          apiKey={`${viewByApiKeyPrefix}_${normalizeKpiConfig(config.kpiName)}`}
          dataApiKey={viewByDataApiKey}
          params={{}}
          stateKey="waterfall_view_by"
          contextKey={contextKey}
          valueLabel="View by:"
          shape="pill"
          size="medium"
          chips
          clearChips={false}
          disabled={isViewByDisabled}
          onValueChange={handleViewByChange}
        />
      </>
    ),
    [
      config.kpiName,
      contextKey,
      isViewByDisabled,
      handleViewByChange,
      viewByApiKeyPrefix,
      viewByDataApiKey,
      segmentControl,
    ],
  );

  return (
    <BasicContainer
      header={{
        title,
        measure,
        tooltip,
        titleSize: 'H4',
        rightContent,
      }}
      layout={{
        border: 'small',
        shadow: 'small',
        headerPadding: 'small',
        bodyPadding: false,
        bottomSeparator: 'border',
      }}
      fullWidth
    >
      <DataStateHandler
        loading={loading}
        error={error}
        empty={!chartData}
        message={{
          description: formatMessage({
            id: 'Common.dataUnavailable.title',
            defaultMessage: 'Data not available',
          }),
        }}
        skeletonProps={skeletonProps}
      >
        {selectedView === 'chart' || !hasTableView ? (
          <WaterfallContent
            chartData={chartData}
            disabledIndexes={disabledIndexes}
            legendItems={legendItems}
            shouldShowLegend={shouldShowLegend}
            onBarClick={handleBarClick}
          />
        ) : (
          <KpiDrillDownTable
            data={tableData as TableDataType}
            tableStyle={StyledDrillDownTable}
          />
        )}
      </DataStateHandler>
    </BasicContainer>
  );
};
